    """Helper function to calculate the sum of proper divisors of n."""
    total = 1  # 1 is always a proper divisor
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def amicable_numbers_sum(n):
    """Function to sum all amicable numbers from 1 to n."""
    summed = set()
    for i in range(2, n + 1):
        j = sum_of_divisors(i)
        if j <= n and j != i and i == sum_of_divisors(j):
            summed.add(i)
            summed.add(j)
