        cumulative_sum += mapping[value]

        # If the cumulative sum is positive, it means there are more zeros
        if cumulative_sum > 0:
            max_diff = max(max_diff, cumulative_sum)
        else:
            # If cumulative_sum is zero, it means equal number of zeros and ones
