                max_diff = max(max_diff, i + 1)
            else:
                # If cumulative_sum is negative and not seen before, update the max_diff
                if cumulative_sum not in first_occurrence:
                    first_occurrence[cumulative_sum] = i
                else:
                    # Calculate the difference with the first occurrence
                    max_diff = max(max_diff, i - first_occurrence[cumulative_sum])

